"""Small YAML 1.2 subset reader/writer for jd's JSON-compatible documents."""
import json, re

def scalar(s):
    s=s.strip()
    if not s: return None
    if s in ('null','Null','NULL','~'): return None
    if s.lower() in ('true','false'): return s.lower()=='true'
    if s.startswith(('"',"'",'[','{')):
        try: return json.loads(s)
        except Exception:
            if s[0]=="'" and s[-1:]=="'": return s[1:-1].replace("''", "'")
    if re.fullmatch(r'[-+]?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?',s):
        try: return int(s) if not any(c in s for c in '.eE') else float(s)
        except Exception: pass
    if s.startswith('#'): return None
    return s

def loads(src):
    lines=[]
    for raw in src.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#') or raw.strip() in ('---','...'): continue
        ind=len(raw)-len(raw.lstrip(' ')); lines.append((ind,raw.strip()))
    if not lines: return None
    def block(i, indent):
        islist=lines[i][1].startswith('- ') or lines[i][1]=='-'
        out=[] if islist else {}
        while i<len(lines) and lines[i][0]==indent:
            t=lines[i][1]
            if islist:
                if not (t=='-' or t.startswith('- ')): break
                rest=t[1:].strip(); i+=1
                if not rest:
                    if i<len(lines) and lines[i][0]>indent: v,i=block(i,lines[i][0])
                    else: v=None
                elif re.match(r'[^\[\]{}"\']+:',rest):
                    k,val=rest.split(':',1); v={k.strip():scalar(val)}
                    if i<len(lines) and lines[i][0]>indent:
                        extra,i=block(i,lines[i][0]);
                        if isinstance(extra,dict): v.update(extra)
                else: v=scalar(rest)
                out.append(v)
            else:
                if ':' not in t: i+=1; continue
                k,val=t.split(':',1); k=scalar(k); val=val.strip(); i+=1
                if val: v=scalar(val)
                elif i<len(lines) and lines[i][0]>indent: v,i=block(i,lines[i][0])
                else: v=None
                out[k]=v
        return out,i
    return block(0,lines[0][0])[0]

def dumps(obj):
    def safe(s): return bool(s) and re.fullmatch(r'[A-Za-z_][\w./ -]*',s) and s.lower() not in ('true','false','null','yes','no')
    def atom(v):
        if isinstance(v,str): return v if safe(v) else json.dumps(v,ensure_ascii=False)
        return 'null' if v is None else ('true' if v is True else 'false' if v is False else json.dumps(v,separators=(',',':'),ensure_ascii=False))
    def emit(v,lev):
        pad=' '*lev
        if isinstance(v,dict):
            if not v: return [pad+'{}']
            res=[]
            for k,x in v.items():
                key=atom(str(k))
                if isinstance(x,(dict,list)) and x: res.append(pad+key+':'); res+=emit(x,lev+2)
                else: res.append(pad+key+': '+atom(x))
            return res
        if isinstance(v,list):
            if not v:return [pad+'[]']
            res=[]
            for x in v:
                if isinstance(x,(dict,list)) and x: res.append(pad+'-');res+=emit(x,lev+2)
                else:res.append(pad+'- '+atom(x))
            return res
        return [pad+atom(v)]
    return '\n'.join(emit(obj,0))+'\n'

"""JSON Merge Patch and JSON Patch application helpers."""
import copy


def merge_patch(target, patch):
    """Apply RFC 7386 merge patch and return a new JSON-compatible value."""
    if not isinstance(patch, dict):
        return copy.deepcopy(patch)
    out = copy.deepcopy(target) if isinstance(target, dict) else {}
    for key, value in patch.items():
        if value is None:
            out.pop(key, None)
        else:
            out[key] = merge_patch(out.get(key), value)
    return out


def _parts(pointer):
    if pointer == "":
        return []
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("invalid JSON pointer")
    parts = []
    for raw in pointer[1:].split("/"):
        i = 0
        while i < len(raw):
            if raw[i] == "~":
                if i + 1 >= len(raw) or raw[i + 1] not in "01":
                    raise ValueError("invalid JSON pointer escape")
                i += 2
            else:
                i += 1
        parts.append(raw.replace("~1", "/").replace("~0", "~"))
    return parts


def _index(part, length, allow_end=False):
    if not part or (len(part) > 1 and part[0] == "0") or not part.isdigit():
        raise ValueError("invalid array index")
    index = int(part)
    if index > length or (index == length and not allow_end):
        raise ValueError("array index out of range")
    return index


def _get(root, path):
    cur = root
    for part in path:
        cur = cur[_index(part, len(cur))] if isinstance(cur, list) else cur[part]
    return cur


def _parent(root, path):
    if not path:
        return None, None
    return _get(root, path[:-1]), path[-1]


def _remove(root, path):
    if not path:
        return None
    parent, key = _parent(root, path)
    if isinstance(parent, list):
        return parent.pop(_index(key, len(parent)))
    return parent.pop(key)


def _add(root, path, value):
    if not path:
        return copy.deepcopy(value)
    parent, key = _parent(root, path)
    value = copy.deepcopy(value)
