"""Core renderer for the jd structural diff format."""
import json
from difflib import SequenceMatcher

def _j(v):
    return json.dumps(v, ensure_ascii=False, separators=(',', ':'))

def render_diff(a, b):
    hunks=[]
    def atom(path, old, new):
        lines=['@ '+_j(path), '- '+_j(old), '+ '+_j(new)]
        hunks.append('\n'.join(lines))
    def rec(path,x,y):
        if type(x)==type(y) and x==y:return
        if isinstance(x,dict) and isinstance(y,dict):
            for k in sorted(set(x)|set(y), key=lambda z: str(z)):
                if k not in y: hunks.append('@ '+_j(path+[k])+'\n- '+_j(x[k]))
                elif k not in x: hunks.append('@ '+_j(path+[k])+'\n+ '+_j(y[k]))
                else: rec(path+[k],x[k],y[k])
            return
        if isinstance(x,list) and isinstance(y,list):
            # Preserve structural paths for same-position object edits.
            if len(x)==len(y) and any(isinstance(a,dict) and isinstance(b,dict) for a,b in zip(x,y)):
                for i,(u,v) in enumerate(zip(x,y)): rec(path+[i],u,v)
                return
            sm=SequenceMatcher(a=[_j(v) for v in x],b=[_j(v) for v in y],autojunk=False)
            ops=[]
            for tag,i1,i2,j1,j2 in sm.get_opcodes():
                if tag=='equal': ops.extend((' ',x[k]) for k in range(i1,i2))
                else:
                    ops.extend(('-',x[k]) for k in range(i1,i2));ops.extend(('+',y[k]) for k in range(j1,j2))
            if all(t==' ' for t,_ in ops):return
            first=next(i for i,z in enumerate(ops) if z[0]!=' '); last=max(i for i,z in enumerate(ops) if z[0]!=' ')
            # jd array hunks include the nearest item on either side as context.
            lo=max(0,first-1); hi=min(len(ops),last+2)
            selected=ops[lo:hi]
            changed_path=path+[sum(1 for t,_ in ops[:first] if t==' ')]
            out=['@ '+_j(changed_path)]
            if len(x)==0: out.append('[')
            out.extend(('  ' if t==' ' else t+' ')+_j(v) for t,v in selected)
            if len(x)!=len(y) or len(x)==0: out.append(']')
            hunks.append('\n'.join(out));return
        atom(path,x,y)
    rec([],a,b)
    return '\n'.join(hunks)+('\n' if hunks else '')

