"""Apply the native jd line-oriented patch format."""
import json
import copy


def _decode_path(s):
    try:
        p = json.loads(s)
    except Exception as e:
        raise ValueError("invalid path") from e
    if not isinstance(p, list):
        raise ValueError("invalid path")
    return p


def _value(s):
    try:
        return json.loads(s)
    except Exception as e:
        raise ValueError("invalid value in jd patch") from e


def _parent(root, path):
    cur = root
    for key in path:
        if isinstance(cur, list) and isinstance(key, int):
            if key < 0 or key >= len(cur):
                raise ValueError(f"path index out of range: {key}")
            cur = cur[key]
        elif isinstance(cur, list) and isinstance(key, dict):
            # setkeys paths encode the identifying fields of an object.
            found = next((item for item in cur if isinstance(item, dict) and
                          all(k in item and _equal(item[k], v) for k, v in key.items())), None)
            if found is None:
                raise ValueError(f"path object not found: {key}")
            cur = found
        elif isinstance(cur, list) and key == {}:
            # A set path addresses a collection as a whole; the next path segment
            # is not generally traversable without a concrete element.
            raise ValueError("cannot traverse a set marker")
        elif isinstance(cur, dict) and isinstance(key, str):
            if key not in cur:
                raise ValueError(f"path key not found: {key}")
            cur = cur[key]
        else:
            raise ValueError("path does not match document")
    return cur


def _equal(a, b):
    return type(a) is type(b) and a == b


def _apply(root, path, removed, added):
    if not path:
        old = removed[0] if removed else None
        if removed and not _equal(root, old):
            raise ValueError("root value does not match patch")
        return copy.deepcopy(added[0]) if added else None
    par = _parent(root, path[:-1])
    key = path[-1]
    if isinstance(key, int) and isinstance(par, list):
        idx = key
        if idx < 0 or idx > len(par):
            raise ValueError(f"array index out of range: {idx}")
        for old in removed:
            if idx >= len(par) or not _equal(par[idx], old):
                raise ValueError(f"found {par[idx] if idx < len(par) else 'nothing'} at {path}: expected {old}")
            del par[idx]
        for j, val in enumerate(added):
            par.insert(idx + j, copy.deepcopy(val))
        return root
    if isinstance(key, str) and isinstance(par, dict):
        if removed:
            if key not in par or not _equal(par[key], removed[0]):
                got = par.get(key, "nothing")
                raise ValueError(f"found {got} at {path}: expected {removed[0]}")
            del par[key]
        if added:
            par[key] = copy.deepcopy(added[-1])
        return root
    # Set and setkeys path markers identify an element inside an array.
    if isinstance(par, list) and (key == {} or key == [] or isinstance(key, dict) or
                                  isinstance(key, list)):
        for val in removed:
            for i, item in enumerate(par):
                if _equal(item, val):
                    del par[i]
                    break
            else:
                raise ValueError(f"expected {val} in array")
        par.extend(copy.deepcopy(added))
