import sys,json,os,argparse,difflib
from diffutil import render_diff
from jdpatch import apply_patch
import yamlutil

def js(v): return json.dumps(v,ensure_ascii=False,separators=(',',':'),sort_keys=True)
def jline(v): return json.dumps(v,ensure_ascii=False,separators=(',', ':'),sort_keys=True)

class Diff:
 def __init__(self,prec=0,setmode=None,setkeys=None,pathopts=None): self.prec=prec; self.setmode=setmode; self.setkeys=setkeys; self.pathopts=pathopts or []; self.lines=[]
 def options_at(self,path):
  found=[]
  for target, options in self.pathopts:
   if target==path: found.extend(options)
  return found
 def enabled(self,path):
  state=True
  for target, options in self.pathopts:
   if path[:len(target)]==target:
    for option in options:
     if option=='DIFF_OFF': state=False
     elif option=='DIFF_ON': state=True
  return state
 def setting(self,path,name,default):
  value=default
  for option in self.options_at(path):
   if isinstance(option,dict) and name in option: value=option[name]
   elif name=='setmode' and option in ('SET','MULTISET'): value=option
  return value
 def eq(self,a,b,precision=None):
  if precision is None: precision=self.prec
  if isinstance(a,(int,float)) and not isinstance(a,bool) and isinstance(b,(int,float)) and not isinstance(b,bool): return abs(a-b)<=precision
  return type(a)==type(b) and a==b
