  if not self.enabled(path):
   if isinstance(a,dict) and isinstance(b,dict):
    for k in sorted(set(a)|set(b)):
     child=path+[k]
     if k in a and k in b:self.walk(a[k],b[k],child)
     elif self.enabled(child):self.emit(child,[self.val('-' if k in a else '+',(a if k in a else b)[k])])
   elif isinstance(a,list) and isinstance(b,list):
    for i in range(min(len(a),len(b))): self.walk(a[i],b[i],path+[i])
   return
  precision=self.setting(path,'precision',self.prec)
  if self.eq(a,b,precision): return
  if isinstance(a,dict) and isinstance(b,dict):
   for k in sorted(set(a)|set(b)):
    if k not in b:self.emit(path+[k],[self.val('-',a[k])])
    elif k not in a:self.emit(path+[k],[self.val('+',b[k])])
    else:self.walk(a[k],b[k],path+[k])
   return
  if isinstance(a,list) and isinstance(b,list):
   setmode=self.setting(path,'setmode',self.setmode)
   if setmode:
    aa={js(x):x for x in a};bb={js(x):x for x in b}
    rem=[aa[k] for k in sorted(aa.keys()-bb.keys())];add=[bb[k] for k in sorted(bb.keys()-aa.keys())]
    self.emit(path+[{} if setmode=='SET' else []],[self.val('-',x) for x in rem]+[self.val('+',x) for x in add]);return
