"""ANSI coloring for rendered jd diff lines."""
import difflib
import json

RED = "\x1b[31m"
GREEN = "\x1b[32m"
RESET = "\x1b[0m"

def _encoded(fragment):
    return json.dumps(fragment, ensure_ascii=False)[1:-1]

def color_lines(lines, words=False):
    result = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if words and line.startswith("- ") and i + 1 < len(lines) and lines[i + 1].startswith("+ "):
            try:
                old = json.loads(line[2:]); new = json.loads(lines[i + 1][2:])
            except Exception:
                old = new = None
            if isinstance(old, str) and isinstance(new, str):
                oldparts, newparts = [], []
                for op, a0, a1, b0, b1 in difflib.SequenceMatcher(a=old, b=new, autojunk=False).get_opcodes():
                    if op == "equal":
                        oldparts.append(_encoded(old[a0:a1]))
                    elif op in ("delete", "replace"):
                        oldparts.extend(RED + _encoded(ch) + RESET for ch in old[a0:a1])
                    if op in ("equal", "delete"):
                        newparts.append(_encoded(new[b0:b1]))
                    elif op == "insert":
                        newparts.extend(GREEN + _encoded(ch) + RESET for ch in new[b0:b1])
                    elif op == "replace":
                        newparts.extend(GREEN + _encoded(ch) + RESET for ch in new[b0:b1])
                result.append('- "' + "".join(oldparts) + '"')
                result.append('+ "' + "".join(newparts) + '"')
                i += 2
                continue
        if line.startswith("- "):
            result.append(RED + line + "\n" + RESET)
        elif line.startswith("+ "):
            result.append(GREEN + line + "\n" + RESET)
        else:
            result.append(line)
        i += 1
    return result

def color_text(lines, words=False):
    colored = color_lines(lines, words)
    out = []
    for i, line in enumerate(colored):
        if i and not out[-1].endswith(RESET):
            out.append("\n")
        out.append(line)
    # Whole-line coloring places the reset after its line terminator. This
    # means the output line itself already contains its newline.
    if any(line.startswith((RED, GREEN)) and line.endswith(RESET) for line in colored):
        return "".join(out)
    return "\n".join(colored) + ("\n" if colored else "")

