"""Core renderer for the jd structural diff format."""
import json
from difflib import SequenceMatcher
import jsonutil

def _normalize(v):
    if isinstance(v, float) and v.is_integer() and abs(v)<1e21: return int(v)
    if isinstance(v, list): return [_normalize(x) for x in v]
    if isinstance(v, dict): return {k: _normalize(x) for k, x in v.items()}
    return v

def _j(v):
    return json.dumps(_normalize(v), ensure_ascii=False, separators=(',', ':'), sort_keys=True)

def _equal(x, y):
    if isinstance(x, bool) or isinstance(y, bool):
        return isinstance(x, bool) and isinstance(y, bool) and x == y
    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        return x == y
    if isinstance(x, dict) and isinstance(y, dict):
        return x.keys() == y.keys() and all(_equal(x[k], y[k]) for k in x)
    if isinstance(x, list) and isinstance(y, list):
        return len(x) == len(y) and all(_equal(a, b) for a, b in zip(x, y))
    return type(x) is type(y) and x == y

def _array_edits(x, y):
    """Minimal array edits via LCS, matching backtracking tie behavior."""
    a,b=[_j(v) for v in x],[_j(v) for v in y]
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for j in range(1,m+1):
            dp[i][j]=dp[i-1][j-1]+1 if a[i-1]==b[j-1] else max(dp[i-1][j],dp[i][j-1])
    i,j=n,m; matches=[]
    while i and j:
        if a[i-1]==b[j-1]:
            matches.append((i-1,j-1)); i-=1; j-=1
        elif dp[i-1][j]>=dp[i][j-1]: i-=1
        else: j-=1
    matches.reverse(); edits=[]; pi=pj=0
    for mi,mj in matches+[(n,m)]:
        if pi<mi or pj<mj: edits.append((pi,mi,pj,mj))
        pi,pj=mi+1,mj+1
    return edits

def render_diff(a, b, base_path=None):
    hunks=[]
    if base_path is None: base_path=[]
    def atom(path, old, new):
        hunks.append('\n'.join(['@ '+_j(path), '- '+_j(old), '+ '+_j(new)]))
    def rec(path, x, y):
