"""Core renderer for the jd structural diff format."""
import json
from difflib import SequenceMatcher
import jsonutil

def _normalize(v):
    if isinstance(v, float) and v.is_integer() and abs(v)<1e21: return int(v)
    if isinstance(v, list): return [_normalize(x) for x in v]
    if isinstance(v, dict): return {k: _normalize(x) for k, x in v.items()}
    return v

def _j(v):
    return jsonutil.dumps(_normalize(v), ensure_ascii=False, separators=(',', ':'), sort_keys=True)

def _equal(x, y):
    if isinstance(x, bool) or isinstance(y, bool):
        return isinstance(x, bool) and isinstance(y, bool) and x == y
    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        return x == y
    if isinstance(x, dict) and isinstance(y, dict):
        return x.keys() == y.keys() and all(_equal(x[k], y[k]) for k in x)
    if isinstance(x, list) and isinstance(y, list):
        return len(x) == len(y) and all(_equal(a, b) for a, b in zip(x, y))
    return type(x) is type(y) and x == y

def _array_edits(x, y, left_keys=None, right_keys=None):
    """Minimal array edits via LCS, matching backtracking tie behavior."""
    a=left_keys if left_keys is not None else [_j(v) for v in x]
    b=right_keys if right_keys is not None else [_j(v) for v in y]
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for j in range(1,m+1):
            dp[i][j]=dp[i-1][j-1]+1 if a[i-1]==b[j-1] else max(dp[i-1][j],dp[i][j-1])
    i,j=n,m; matches=[]
    while i and j:
        if a[i-1]==b[j-1]:
            matches.append((i-1,j-1)); i-=1; j-=1
        elif dp[i-1][j]>=dp[i][j-1]: i-=1
        else: j-=1
    matches.reverse(); edits=[]; pi=pj=0
    for mi,mj in matches+[(n,m)]:
        if pi<mi or pj<mj: edits.append((pi,mi,pj,mj))
        pi,pj=mi+1,mj+1
    return edits

def render_diff(a, b, base_path=None):
    hunks=[]
    if base_path is None: base_path=[]
    def atom(path, old, new):
        hunks.append('\n'.join(['@ '+_j(path), '- '+_j(old), '+ '+_j(new)]))
    def rec(path, x, y):
        if _equal(x, y): return
        if isinstance(x, dict) and isinstance(y, dict):
            for k in sorted(set(x)|set(y), key=lambda z: str(z)):
                if k not in y: hunks.append('@ '+_j(path+[k])+'\n- '+_j(x[k]))
                elif k not in x: hunks.append('@ '+_j(path+[k])+'\n+ '+_j(y[k]))
                else: rec(path+[k], x[k], y[k])
            return
        if isinstance(x, list) and isinstance(y, list):
            left_keys=[_j(v) for v in x];right_keys=[_j(v) for v in y]
            from collections import Counter
            old_count=Counter(left_keys);new_count=Counter(right_keys)
            for i in range(min(len(x),len(y))):
                if (isinstance(x[i],(dict,list)) and type(x[i])==type(y[i])
                    and old_count[left_keys[i]]>new_count[left_keys[i]]):
                    if not _equal(x[i],y[i]): rec(path+[i],x[i],y[i])
                    left_keys[i]=right_keys[i]=('paired-container',i)
            for i1,i2,j1,j2 in _array_edits(x,y,left_keys,right_keys):
                out=['@ '+_j(path+[j1])]
                if i1==0: out.append('[')
                if i1 and j1: out.append('  '+_j(y[j1-1]))
                elif i1: out.append('  '+_j(x[i1-1]))
