                elif i2<len(x): out.append('  '+_j(x[i2]))
                if i2==len(x): out.append(']')
                hunks.append('\n'.join(out))
            return
        atom(path,x,y)
    rec(list(base_path),a,b)
    return '\n'.join(hunks)+('\n' if hunks else '')
